CREATE TABLE backtest_definitions (definition_id UUID PRIMARY KEY, name TEXT NOT NULL, strategies JSONB NOT NULL, start_at TIMESTAMPTZ NOT NULL, end_at TIMESTAMPTZ NOT NULL, initial_cash NUMERIC NOT NULL CHECK(initial_cash>0), base_currency CHAR(3) NOT NULL, data_snapshot_id UUID NOT NULL, universe_snapshot_id UUID NOT NULL, code_version TEXT NOT NULL, random_seed INTEGER NOT NULL, max_participation NUMERIC NOT NULL CHECK(max_participation>0 AND max_participation<=1), execution_delay_bars INTEGER NOT NULL CHECK(execution_delay_bars>=1), benchmark_id UUID, delisting_policy TEXT NOT NULL);
CREATE TABLE backtest_runs (run_id UUID PRIMARY KEY, definition_id UUID NOT NULL REFERENCES backtest_definitions(definition_id), input_hash TEXT UNIQUE NOT NULL, result_hash TEXT, status TEXT NOT NULL CHECK(status IN ('CREATED','VALIDATING','RUNNING','COMPLETED','FAILED','CANCELLED')), started_at TIMESTAMPTZ, completed_at TIMESTAMPTZ, last_sequence INTEGER NOT NULL DEFAULT 0, error TEXT);
CREATE TABLE backtest_simulation_events (event_id UUID PRIMARY KEY, run_id UUID NOT NULL REFERENCES backtest_runs(run_id), sequence INTEGER NOT NULL, market_time TIMESTAMPTZ NOT NULL, received_at TIMESTAMPTZ NOT NULL, priority INTEGER NOT NULL, event_type TEXT NOT NULL, payload_version TEXT NOT NULL, payload JSONB NOT NULL, causation_id UUID, correlation_id UUID, UNIQUE(run_id,sequence));
CREATE INDEX ix_backtest_event_order ON backtest_simulation_events(run_id,market_time,priority,sequence);
CREATE TABLE backtest_sim_orders (order_id UUID PRIMARY KEY, run_id UUID NOT NULL REFERENCES backtest_runs(run_id), instrument_id UUID NOT NULL, market TEXT NOT NULL, side TEXT NOT NULL, order_type TEXT NOT NULL, quantity INTEGER NOT NULL CHECK(quantity>0), submitted_at TIMESTAMPTZ NOT NULL, eligible_after_bar_sequence INTEGER NOT NULL CHECK(eligible_after_bar_sequence>=1), limit_price NUMERIC, filled_quantity INTEGER NOT NULL CHECK(filled_quantity>=0 AND filled_quantity<=quantity), status TEXT NOT NULL, reason TEXT);
CREATE TABLE backtest_sim_fills (fill_id UUID PRIMARY KEY, run_id UUID NOT NULL REFERENCES backtest_runs(run_id), order_id UUID NOT NULL REFERENCES backtest_sim_orders(order_id), instrument_id UUID NOT NULL, side TEXT NOT NULL, quantity INTEGER NOT NULL CHECK(quantity>0), price NUMERIC NOT NULL CHECK(price>0), gross NUMERIC NOT NULL, commission NUMERIC NOT NULL, tax NUMERIC NOT NULL, platform_fee NUMERIC NOT NULL, slippage_cost NUMERIC NOT NULL, filled_at TIMESTAMPTZ NOT NULL, bar_id UUID NOT NULL);
CREATE TABLE backtest_sim_ledger (entry_id UUID PRIMARY KEY, run_id UUID NOT NULL REFERENCES backtest_runs(run_id), kind TEXT NOT NULL, effective_at TIMESTAMPTZ NOT NULL, source_id UUID NOT NULL, cash_delta NUMERIC NOT NULL DEFAULT 0, instrument_id UUID, quantity_delta INTEGER NOT NULL DEFAULT 0, fee_delta NUMERIC NOT NULL DEFAULT 0);
CREATE TABLE backtest_snapshots (snapshot_id UUID PRIMARY KEY, run_id UUID NOT NULL REFERENCES backtest_runs(run_id), as_of TIMESTAMPTZ NOT NULL, cash NUMERIC NOT NULL, positions JSONB NOT NULL, nav NUMERIC NOT NULL, sleeve_exposure JSONB NOT NULL, content_hash TEXT NOT NULL);
CREATE TABLE backtest_metrics (metric_id UUID PRIMARY KEY, run_id UUID NOT NULL REFERENCES backtest_runs(run_id), name TEXT NOT NULL, value NUMERIC, unit TEXT NOT NULL, scope TEXT NOT NULL, UNIQUE(run_id,name,scope));
CREATE TABLE backtest_artifacts (artifact_id UUID PRIMARY KEY, run_id UUID NOT NULL REFERENCES backtest_runs(run_id), artifact_type TEXT NOT NULL, content_hash TEXT NOT NULL, reference TEXT NOT NULL);
CREATE TABLE backtest_sleeve_contributions (contribution_id UUID PRIMARY KEY, run_id UUID NOT NULL REFERENCES backtest_runs(run_id), strategy_run_id UUID NOT NULL, kind TEXT NOT NULL, instrument_id UUID NOT NULL, raw_weight NUMERIC NOT NULL, final_weight NUMERIC NOT NULL);
